//! Fixed opaque triangle queries on the existing device and frame queue.
use crate::{protocol::{Program,words},ray_contract::{Geometry,Scene,matrix}};use std::collections::BTreeMap;use wgpu::util::DeviceExt;
struct Pipelines{gather:wgpu::ComputePipeline,query:wgpu::ComputePipeline,coverage:wgpu::ComputePipeline,dummy:wgpu::Buffer}
struct Model{spec:Scene,sources:Vec<usize>,instances:Vec<usize>,starts:Vec<u32>,inputs:Vec<wgpu::Buffer>,packed:wgpu::Buffer,bases:wgpu::Buffer,invalid:wgpu::Buffer,blas:Vec<wgpu::Blas>,sizes:Vec<wgpu::BlasTriangleGeometrySizeDescriptor>,tlas:wgpu::Tlas,pose:Vec<u32>,built:bool,as_bytes:u64}
pub struct Rays{pipelines:Option<Pipelines>,models:BTreeMap<(usize,usize),Model>,queries:u64,completed:u64,pending:BTreeMap<usize,u64>,builds:u64,tlas_builds:u64,cache:u64,retired:u64}
fn buffer(d:&wgpu::Device,n:u64,usage:wgpu::BufferUsages)->wgpu::Buffer{d.create_buffer(&wgpu::BufferDescriptor{label:Some("native-ray/private"),size:n,usage,mapped_at_creation:false})}
fn pipeline(d:&wgpu::Device,code:&str)->wgpu::ComputePipeline{let module=d.create_shader_module(wgpu::ShaderModuleDescriptor{label:Some("native-ray/fixed-profile"),source:wgpu::ShaderSource::Wgsl(code.into())});d.create_compute_pipeline(&wgpu::ComputePipelineDescriptor{label:Some("native-ray/fixed-profile"),layout:None,module:&module,entry_point:Some("main"),compilation_options:Default::default(),cache:None})}
fn groups(count:u32,limit:u32)->[u32;2]{let n=count.div_ceil(64);let x=n.min(limit);[x,n.div_ceil(x)]}
fn gather_geometry<'a>(pipe:&Pipelines,d:&wgpu::Device,encoder:&mut wgpu::CommandEncoder,geometries:impl IntoIterator<Item=&'a Geometry>,data:&[wgpu::Buffer],packed:&wgpu::Buffer,invalid:&wgpu::Buffer){let mut base=0;encoder.clear_buffer(invalid,0,None);for g in geometries{let source=&data[g.positions];let uniform=d.create_buffer_init(&wgpu::util::BufferInitDescriptor{label:None,contents:&words(&[g.count,base,(source.size()/12)as u32,u32::from(g.indices.is_some())]),usage:wgpu::BufferUsages::UNIFORM});let refs=[source,g.indices.map(|i|&data[i]).unwrap_or(&pipe.dummy),packed,invalid,&uniform];let group=d.create_bind_group(&wgpu::BindGroupDescriptor{label:None,layout:&pipe.gather.get_bind_group_layout(0),entries:&refs.iter().enumerate().map(|(i,b)|wgpu::BindGroupEntry{binding:i as u32,resource:b.as_entire_binding()}).collect::<Vec<_>>()});let n=groups(g.count/3,d.limits().max_compute_workgroups_per_dimension);{let mut pass=encoder.begin_compute_pass(&Default::default());pass.set_pipeline(&pipe.gather);pass.set_bind_group(0,&group,&[]);pass.dispatch_workgroups(n[0],n[1],1);}base+=g.count;}}
impl Rays{
 pub fn new(device:&wgpu::Device,enabled:bool)->Self{let pipelines=enabled.then(||Pipelines{gather:pipeline(device,include_str!("ray/gather.wgsl")),query:pipeline(device,include_str!("ray/query.wgsl")),coverage:pipeline(device,&include_str!("ray/query.wgsl")
 .replace("// FW_COVERAGE_HELPERS",include_str!("ray/coverage.wgsl"))
 .replace("/* FW_RAY_FLAGS */0u","RAY_FLAG_FORCE_NO_OPAQUE")
 .replace("/* FW_COVERAGE_CANDIDATE */","let candidate=rayQueryGetCandidateIntersection(&rq);if(visibleCandidate(candidate,d,i)){rayQueryConfirmIntersection(&rq);}")),dummy:buffer(device,4,wgpu::BufferUsages::STORAGE)});Self{pipelines,models:BTreeMap::new(),queries:0,completed:0,pending:BTreeMap::new(),builds:0,tlas_builds:0,cache:0,retired:0}}
 pub fn reserved_bytes(&self)->u64{self.models.values().map(|m|m.as_bytes).sum()}
 pub fn gather_buffers(&self,d:&wgpu::Device,encoder:&mut wgpu::CommandEncoder,spec:&Scene,data:&[wgpu::Buffer],packed:&wgpu::Buffer,invalid:&wgpu::Buffer)->Result<(),String>{let pipe=self.pipelines.as_ref().ok_or("E_NATIVE_RAY_PERMISSION: explicit ray authorization required")?;gather_geometry(pipe,d,encoder,&spec.geometries,data,packed,invalid);Ok(())}
 pub fn build(&mut self,d:&wgpu::Device,encoder:&mut wgpu::CommandEncoder,_p:&Program,slot:usize,index:usize,spec:&Scene,pose:&[u32],immutable:bool,data:&[wgpu::Buffer],base_bytes:u64,budget:u64)->Result<(),String>{
  let pipe=self.pipelines.as_ref().ok_or("E_NATIVE_RAY_PERMISSION: ray query requires explicit operator opt-in")?;let limits=d.limits();let instance_count=spec.geometries.len();
  if instance_count>limits.max_tlas_instance_count as usize||instance_count as u64*16>limits.max_storage_buffer_binding_size as u64{return Err("E_NATIVE_RAY_LIMIT: instance count exceeds actual device limit".into());}
  if self.models.get(&(slot,index)).is_some_and(|m|m.spec!=*spec){self.models.remove(&(slot,index));self.retired+=1;}
  if !self.models.contains_key(&(slot,index)){
   let (sources,instances)=spec.blas_layout();
   let counts=sources.iter().map(|&i|spec.geometries[i].count).collect::<Vec<_>>();
   let total=counts.iter().map(|&n|u64::from(n)).sum::<u64>();
   if counts.iter().any(|&n|n/3>limits.max_blas_primitive_count)||total*12>limits.max_storage_buffer_binding_size as u64||total>u32::MAX as u64{return Err("E_NATIVE_RAY_LIMIT: geometry exceeds actual AS/storage device limits".into());}
   let starts=counts.iter().scan(0u32,|start,&n|{let offset=*start;*start+=n;Some(offset)}).collect();
   let as_bytes=crate::ray_policy::bytes(d,&counts,instance_count as u32,spec.quality=="trace")?;let allocated=self.models.values().map(|m|m.as_bytes).sum::<u64>();if base_bytes.checked_add(allocated).and_then(|v|v.checked_add(as_bytes)).is_none_or(|n|n>budget){return Err("E_NATIVE_RAY_BUDGET: driver-reported AS + scratch reservation exceeds caller budget; reduce slots/geometry or raise memory budget explicitly".into());}
   let sizes=counts.iter().map(|&n|wgpu::BlasTriangleGeometrySizeDescriptor{vertex_format:wgpu::VertexFormat::Float32x3,vertex_count:n,index_format:None,index_count:None,flags:wgpu::AccelerationStructureGeometryFlags::OPAQUE}).collect::<Vec<_>>();let flags=if spec.quality=="trace"{wgpu::AccelerationStructureFlags::PREFER_FAST_TRACE}else{wgpu::AccelerationStructureFlags::PREFER_FAST_BUILD};let blas=sizes.iter().map(|s|d.create_blas(&wgpu::CreateBlasDescriptor{label:Some("native-ray/BLAS"),flags,update_mode:wgpu::AccelerationStructureUpdateMode::Build},wgpu::BlasGeometrySizeDescriptors::Triangles{descriptors:vec![s.clone()]})).collect();let tlas=d.create_tlas(&wgpu::CreateTlasDescriptor{label:Some("native-ray/TLAS"),max_instances:instance_count as u32,flags,update_mode:wgpu::AccelerationStructureUpdateMode::Build});self.models.insert((slot,index),Model{spec:spec.clone(),sources,instances,starts,inputs:vec![],packed:buffer(d,total*12,wgpu::BufferUsages::STORAGE|wgpu::BufferUsages::BLAS_INPUT),bases:buffer(d,instance_count as u64*16,wgpu::BufferUsages::STORAGE|wgpu::BufferUsages::COPY_DST),invalid:buffer(d,4,wgpu::BufferUsages::STORAGE|wgpu::BufferUsages::COPY_DST),blas,sizes,tlas,pose:vec![],built:false,as_bytes});}
  if base_bytes.checked_add(self.models.values().map(|m|m.as_bytes).sum()).is_none_or(|n|n>budget){return Err("E_NATIVE_RAY_BUDGET: active AS reservation exceeds caller budget".into());}
  let m=self.models.get_mut(&(slot,index)).unwrap();let inputs=if immutable{m.sources.iter().map(|&i|&spec.geometries[i]).flat_map(|g|std::iter::once(data[g.positions].clone()).chain(g.indices.map(|i|data[i].clone()))).collect::<Vec<_>>()}else{vec![]};let geometry_dirty=!m.built||!immutable||m.inputs!=inputs;let pose_dirty=!m.built||m.pose!=pose;if !geometry_dirty&&!pose_dirty{self.cache+=1;return Ok(());}let mut entries=Vec::with_capacity(instance_count*4);
  if geometry_dirty{gather_geometry(pipe,d,encoder,m.sources.iter().map(|&i|&spec.geometries[i]),data,&m.packed,&m.invalid);self.builds+=1;}
  for (i,g)in spec.geometries.iter().enumerate(){let (transform,sign)=matrix(&pose[i*12..i*12+12])?;let instance=m.instances[i];m.tlas[i]=Some(wgpu::TlasInstance::new(&m.blas[instance],transform,g.id,g.mask));entries.extend_from_slice(&[m.starts[instance],g.count,sign.to_bits(),0]);}
  // Metadata is copied with this encoder, preserving order across multiple scenes.
  let seed=d.create_buffer_init(&wgpu::util::BufferInitDescriptor{label:None,contents:&words(&entries),usage:wgpu::BufferUsages::COPY_SRC});encoder.copy_buffer_to_buffer(&seed,0,&m.bases,0,seed.size());let mut first=0;let builds=m.blas.iter().zip(&m.sizes).map(|(blas,size)|{let entry=wgpu::BlasBuildEntry{blas,geometry:wgpu::BlasGeometries::TriangleGeometries(vec![wgpu::BlasTriangleGeometry{size,vertex_buffer:&m.packed,first_vertex:first,vertex_stride:12,index_buffer:None,first_index:None,transform_buffer:None,transform_buffer_offset:None}])};first+=size.vertex_count;entry}).collect::<Vec<_>>();encoder.build_acceleration_structures(builds.iter().filter(|_|geometry_dirty),[&m.tlas]);self.tlas_builds+=1;m.pose=pose.to_vec();m.inputs=inputs;m.built=true;Ok(())
 }
 pub fn query(&mut self,d:&wgpu::Device,encoder:&mut wgpu::CommandEncoder,slot:usize,index:usize,bindings:&[usize],header:&[u32],data:&[wgpu::Buffer])->Result<(),String>{let m=self.models.get(&(slot,index)).ok_or("E_NATIVE_RAY_SEQUENCE: build scene before query")?;let p=self.pipelines.as_ref().ok_or("E_NATIVE_RAY_PERMISSION: disabled")?;let uniform=d.create_buffer_init(&wgpu::util::BufferInitDescriptor{label:None,contents:&words(&header[..4]),usage:wgpu::BufferUsages::UNIFORM});let mut entries=vec![wgpu::BindGroupEntry{binding:0,resource:wgpu::BindingResource::AccelerationStructure(&m.tlas)}];let extra=bindings.len()==7;let query=if extra{&p.coverage}else{&p.query};
let alpha_uniform=d.create_buffer_init(&wgpu::util::BufferInitDescriptor{label:None,contents:&words(&header[4..8]),usage:wgpu::BufferUsages::UNIFORM});
let mut refs=bindings[..5].iter().map(|&i|&data[i]).chain([&m.packed,&m.bases,&m.invalid,&uniform]).collect::<Vec<_>>();
if extra{refs.extend([&data[bindings[5]],&data[bindings[6]],&alpha_uniform]);}entries.extend(refs.iter().enumerate().map(|(i,b)|wgpu::BindGroupEntry{binding:i as u32+1,resource:b.as_entire_binding()}));let group=d.create_bind_group(&wgpu::BindGroupDescriptor{label:None,layout:&query.get_bind_group_layout(0),entries:&entries});let n=groups(header[0],d.limits().max_compute_workgroups_per_dimension);{let mut pass=encoder.begin_compute_pass(&Default::default());pass.set_pipeline(query);pass.set_bind_group(0,&group,&[]);pass.dispatch_workgroups(n[0],n[1],1);}self.queries+=u64::from(header[0]);*self.pending.entry(slot).or_default()+=u64::from(header[0]);Ok(())}
 pub fn completed(&mut self,slot:usize){self.completed+=self.pending.remove(&slot).unwrap_or(0);}
 pub fn retain(&mut self,p:&Program)->Result<(),String>{let n=self.models.len();self.models.retain(|&(slot,index),m|slot<p.slots&&p.passes.get(index).and_then(|pass|pass.ray_build.as_ref())==Some(&m.spec));self.retired+=(n-self.models.len())as u64;if p.validated_bytes()?.checked_add(self.models.values().map(|m|m.as_bytes).sum()).is_none_or(|n|n>p.max_bytes){return Err("E_NATIVE_RAY_BUDGET: retained AS exceeds caller budget".into());}Ok(())}
 pub fn stats(&self)->serde_json::Value{serde_json::json!({"version":1,"profile":"opaque-triangles-v1","enabled":self.pipelines.is_some(),"runtimeVerified":self.completed>0,"submittedRays":self.queries,"completedRays":self.completed,"geometryBuilds":self.builds,"tlasBuilds":self.tlas_builds,"cachedSceneBuilds":self.cache,"residentScenes":self.models.len(),"residentBlas":self.models.values().map(|m|m.blas.len()).sum::<usize>(),"residentInstances":self.models.values().map(|m|m.instances.len()).sum::<usize>(),"packedGeometryBytes":self.models.values().map(|m|m.packed.size()).sum::<u64>(),"driverReportedAsAndScratchBytes":self.models.values().map(|m|m.as_bytes).sum::<u64>(),"retiredScenes":self.retired,"cpuPixelReadbacks":0,"cpuGeometryReadbacks":0,"refitImplemented":false,"physicalPeakBytes":"unknown"})}
}
